previewCss:
.darma-loader-jump-rope {
  position: relative;
  width: 48px;
  height: 44px;
}
.darma-loader-jump-rope::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 6px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  box-shadow: 30px 0 0 var(--loader-color, #6366f1);
}
.darma-loader-jump-rope i {
  position: absolute;
  top: 9px;
  left: 9px;
  width: 30px;
  height: 32px;
  border: 3px solid var(--loader-color, #6366f1);
  border-radius: 50%;
  box-sizing: border-box;
  transform-origin: top center;
  animation: darma-loader-jump-rope-rope 0.7s ease-in-out infinite;
}
@keyframes darma-loader-jump-rope-rope {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(0.12); }
}

